            own,
            overrides: own && based,
            required: prop.required,
            default_tag: given.default_tag || prop.default_value.is_some() || prop.tags.contains_key("default"),
            documented: !prop.description.is_empty(),
            literal_union: is_literal_union(&prop.prop_type),
